draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H - 50);
  ctx.lineTo(W, H - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H - 30, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 20, H - 30);
  ctx.lineTo(W / 2 - 20, H - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 20, H - 30);
  ctx.lineTo(W / 2 + 20, H - 10);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Park Bench', W / 2, H - 70);
  ctx.beginPath();
  ctx.moveTo(50, H - 100);
  ctx.lineTo(50, H - 50);
  ctx.lineTo(50 + 20 + Math.sin(t) * 10, H - 50);
  ctx.lineTo(50 + 20 + Math.sin(t) * 10, H - 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - 50, H - 100);
  ctx.lineTo(W - 50, H - 50);
  ctx.lineTo(W - 50 - 20 - Math.sin(t) * 10, H - 50);
  ctx.lineTo(W - 50 - 20 - Math.sin(t) * 10, H - 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(100, H - 150, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W - 100, H - 150, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(100, H - 130);
  ctx.lineTo(100, H - 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - 100, H - 130);
  ctx.lineTo(W - 100, H - 100);
  ctx.stroke();
  ctx.restore();
}
